    r'\.[a-zA-Z]{2,})$'
)

def is_valid_email(address: str) -> bool:
    if not address or len(address) > 254:
        return False
    if not _EMAIL_PATTERN.match(address):
        return False
    local, domain = address.rsplit('@', 1)
    if len(local) > 64:
        return False
    if '..' in local:
        return False
    if local.startswith('.') or local.endswith('.'):
        return False
    return True
